161: 	onGlobalFilterChange: (updater) => {
162: 		globalFilter =
163: 			updater instanceof Function ? updater(globalFilter) : updater;
164: 	},
165: 	onSortingChange: (updater) => {
166: 		sorting = updater instanceof Function ? updater(sorting) : updater;
167: 	},
168: 	state: {
169: 		get globalFilter() {
170: 			return globalFilter;
171: 		},
172: 		get sorting() {
173: 			return sorting;
174: 		},
175: 	},
