507: 		return dates;
508: 	}
509: 	let cursor = start.startOf("day");
510: 	while (cursor.day() !== training.schedule.weekday)
511: 		cursor = cursor.add(1, "day");
512: 	while (cursor.isBefore(end, "day")) {
513: 		dates.push(cursor.format(DATE_FORMAT));
514: 		cursor = cursor.add(1, "week");
515: 	}
