593: export function occurrencesBetween(start: Date | string, end: Date | string) {
594: 	const from = dayjs(start);
595: 	const to = dayjs(end);
596: 	const result: Occurrence[] = [];
597: 	for (const training of store.trainings) {
598: 		for (const date of occurrenceDates(training, from, to)) {
599: 			result.push(resolveOccurrence(training, date));
600: 		}
601: 	}
602: 	return result.sort((a, b) =>
603: 		`${a.date} ${a.startTime}`.localeCompare(`${b.date} ${b.startTime}`),
604: 	);
